"""Frozen main table (S4) recomputed from stored probs. Writes v2_reflective/e23/results_frozen.md and paper/figures/e23/main_bars.png. No selection: fixed list of models. Rerun on Nov 1 after seed-2."""
import functools, json, os, re, numpy as np
from scipy.stats import binomtest
import matplotlib; matplotlib.use("Agg"); import matplotlib.pyplot as plt
from sklearn.linear_model import LogisticRegression
from sklearn.metrics import f1_score
D = "v2_reflective/e23/"; rng = np.random.default_rng(0)
G = functools.lru_cache(None)(lambda p, s: {x["review_id"]: x for x in map(json.loads, open(f"{D}{p}_{s}_probs.jsonl" if p.startswith("evid") else f"{D}p1/probs_{p}_{s}.jsonl"))})  # cached: arr() indexes G per row
S = ("dev", "dev2", "eval", "natural_test"); ids = {s: list(G("R", s)) for s in S}; arr = lambda p, s: np.clip([G(p, s)[i]["probs"] for i in ids[s]], 1e-6, 1)
y = {s: np.array([G("R", s)[i]["gt_rating"] - 1 for i in ids[s]]) for s in S}; X = lambda p, s: np.c_[np.log(arr(p, s)), np.log(arr("evid", s))]
stk = {p: LogisticRegression(C=1, max_iter=3000).fit(X(p, "dev"), y["dev"]) for p in ("R", "base", "enc2k")}
models = {"Base LLaMA (no LoRA)": lambda s: arr("base", s).argmax(1), "DistilBERT 2K": lambda s: arr("enc2k", s).argmax(1), "Phase 1: LLaMA + LoRA": lambda s: arr("R", s).argmax(1),
          "Evidence model (TF-IDF, 100K)": lambda s: arr("evid", s).argmax(1), "Base LLaMA + Evidence stack": lambda s: stk["base"].predict(X("base", s)),
          "DistilBERT + Evidence stack": lambda s: stk["enc2k"].predict(X("enc2k", s)), "LoRA + Evidence stack (dev fit)": lambda s: stk["R"].predict(X("R", s))}
# Phase H rows (LOG.md 2026-10-24): P3 = evid7 (frozen base-LLaMA L20 probe), E6b = evid6b (TF-IDF LR ~497K); Reflector fit on dev2
XH = lambda ag, s: np.hstack([np.log(arr(a, s)) for a in ag])
stkH = {k: LogisticRegression(C=1, max_iter=3000).fit(XH(ag, "dev2"), y["dev2"]) for k, ag in (("S0", ("R", "evid")), ("SH", ("evid7", "evid6b")))}
models.update({"LLaMA probe (frozen, layer 20)": lambda s: arr("evid7", s).argmax(1), "Evidence model (TF-IDF, ~497K)": lambda s: arr("evid6b", s).argmax(1),
               "LoRA + Evidence stack (dev2 fit)": lambda s: stkH["S0"].predict(XH(("R", "evid"), s)), "Probe + Evidence stack (main)": lambda s: stkH["SH"].predict(XH(("evid7", "evid6b"), s))})
if os.path.exists(D + "p1/probs_R2_natural_test.jsonl"): stk["R2"] = LogisticRegression(C=1, max_iter=3000).fit(X("R2", "dev"), y["dev"]); models["Phase 1 LoRA, seed 2"] = lambda s: arr("R2", s).argmax(1); models["LoRA seed 2 + Evidence stack"] = lambda s: stk["R2"].predict(X("R2", s))
out = ["# Frozen results (auto-generated by e23/freeze_tables.py; every number recomputed from stored probs)\n", "Exact = 5-class exact match; 95% CI = bootstrap (3,000) on exact. dev is selection data only (stackers fit on it).\n"]; bars = {}
for s in ("eval", "natural_test"):
    out += [f"\n## {s} (n={len(ids[s])})\n", "| Model | Exact % [95% CI] | macro-F1 | within-1 % | MAE |", "|---|---|---|---|---|"]; bars[s] = []
    for n, f in models.items():
        p = f(s); c = (p == y[s]).astype(float); bs = [c[rng.integers(0, len(c), len(c))].mean() for _ in range(3000)]; lo, hi = np.percentile(bs, [2.5, 97.5])
        out.append(f"| {n} | {c.mean()*100:.1f} [{lo*100:.1f}, {hi*100:.1f}] | {f1_score(y[s], p, average='macro'):.3f} | {(abs(p-y[s])<=1).mean()*100:.1f} | {abs(p-y[s]).mean():.3f} |"); bars[s].append((n, c.mean() * 100, lo * 100, hi * 100))
out.append("\nPrior-corrected natural_test rows, paired comparisons, variance and Gate 0 are in `LOG.md` (2026-10-18, 10-20, 10-21) with outputs `stack_week1.out`, `prior_baseline.out`, `base_vs_lora.out`, `variance.out`, `gate0_e23.out`, `encoder_2k.out`. Phase H (SH main config): `readout_H.out` (paired tests), `variance_H.out` (5 seeds, E6b fixed), `gate_H.out`.")
open(D + "results_frozen.md", "w").write("\n".join(out) + "\n"); print("\n".join(out))
fig, ax = plt.subplots(1, 2, figsize=(11, 4.5), sharey=True)
for a, s in zip(ax, bars):
    b = bars[s]; a.barh([x[0] for x in b], [x[1] for x in b], xerr=[[x[1] - x[2] for x in b], [x[3] - x[1] for x in b]], color=["#C44E52" if "(main)" in x[0] else "#4C72B0" for x in b]); a.set_title(s); a.set_xlabel("exact %"); a.invert_yaxis()
plt.tight_layout(); plt.savefig("paper/figures/e23/main_bars.png", dpi=150)

# ---- Phase 2 v3 (Router, Explainer + Critic), copied from b2_report.json; written to results_frozen.md
import os
if os.path.exists(D + "b2_report.json"):
    B = json.load(open(D + "b2_report.json")); lines = ["", "## Phase 2 v3: Router and explanations (all 3,000 test reviews)", "",
        "| Split | Faithful first draft | Faithful after Critic loop | McNemar p | Rewrite rate | Mean rounds | Comprehensiveness cited / random | Sufficiency cited / random | LLM calls / review |", "|---|---|---|---|---|---|---|---|---|"]
    for s in ("eval", "natural_test"):
        b = B[s]; lines.append(f"| {s} | {b['faithful_first']:.3f} | {b['faithful_final']:.3f} | {b['mcnemar_p']:.2g} | {b['rewrite_rate']:.3f} | {b['mean_rounds']:.2f} | "
                               f"{b['comp_cited']:.3f} / {b['comp_random']:.3f} | {b['suff_cited']:.3f} / {b['suff_random']:.3f} | {b['llm_calls']:.2f} |")
    ro = B["router"].get("readout", {})
    for s, v in ro.items():
        lines.append(f"\nRouter ({s}, tau {B['router']['tau']}): SH {v['full']:.3f}, routed {v['routed']:.3f}, probe skipped on {v['skip_share']:.1%}, McNemar p {v['mcnemar_p']:.2g}")
    sc = ["", "## Self-correction (three levels)", "", "| Level | Split | Corrected reviews | Fixed | Broken | Net | p |", "|---|---|---|---|---|---|---|"]
    for s, v in ro.items():
        e_ = v["sc1"]; sc.append(f"| SC1 escalation (rating) | {s} | {e_['escalated']} escalated | {e_['fixed']} | {e_['broken']} | {e_['net']:+d} | {e_['p']:.2g} |")
    if os.path.exists(D + "gate_SC2.json"):
        S2 = json.load(open(D + "gate_SC2.json"))
        for s in ("dev2", "natural_dev", "eval", "natural_test"):
            v = S2.get(s) or S2.get("readout", {}).get(s)
            if v: sc.append(f"| SC2 LLM re-rating (rating) | {s} | {v['uncertain']} uncertain, {v['abstained']} abstained | {v['fixed']} | {v['broken']} | {v['net']:+d} | {v['p']:.2g} |")
    for s in ("eval", "natural_test"):
        b = B[s]; f0, f1 = round(b["faithful_first"] * b["n"]), round(b["faithful_final"] * b["n"])
        sc.append(f"| SC3 Critic loop (explanation) | {s} | faithful {b['faithful_first']:.3f} -> {b['faithful_final']:.3f} | {f1 - f0} | 0 | {f1 - f0:+d} | {b['mcnemar_p']:.2g} |")
        i1 = D + f"i1_more_rounds_{s}.out"                                                    # I1: max 4 rewrites (LOG.md 2026-10-28)
        if os.path.exists(i1):
            t = open(i1).read(); fx = int(re.search(r"fixed by rounds 3-4 (\d+)", t).group(1)); m4 = float(re.search(r"max-4 ([\d.]+)", t).group(1))
            sc.append(f"| SC3 Critic loop, max 4 rewrites (I1) | {s} | faithful {b['faithful_first']:.3f} -> {m4:.3f} | {f1 - f0 + fx} | 0 | {f1 - f0 + fx:+d} | {binomtest(f1 - f0 + fx, f1 - f0 + fx).pvalue:.2g} |")
    lines += sc
    open(D + "results_frozen.md", "a").write("\n".join(lines) + "\n"); print("\n".join(lines))
